import json, sys, itertools
from collections import Counter
root = sys.argv[1]; label = sys.argv[2]
POS = ['GKP','DEF','MID','FWD']
P = {}
for pos in POS:
    for r in json.load(open(f'{root}/players-{pos}.json')):
        r['pos']=pos; P[r['id']]=r
boot = json.load(open('data/raw/gw4/bootstrap.json'))
B = {e['id']:e for e in boot['elements']}
SQUAD = {1:6.0,4:8.0,202:5.0,229:6.0,427:7.9,237:5.9,481:6.3,68:6.0,411:15.5,106:7.9,249:5.5,497:4.0,69:6.0,445:5.0,423:4.4}
BANK = 0.0
FORMS = [(1,d,m,f) for d in range(3,6) for m in range(2,6) for f in range(1,4) if 1+d+m+f==11]
def best_xi(ids, gw):
    by = {p:sorted([i for i in ids if P[i]['pos']==p], key=lambda i:-P[i]['ep_gw'][gw]) for p in POS}
    best=None
    for g,d,m,f in FORMS:
        if len(by['DEF'])<d or len(by['MID'])<m or len(by['FWD'])<f: continue
        xi = by['GKP'][:1]+by['DEF'][:d]+by['MID'][:m]+by['FWD'][:f]
        ep = sum(P[i]['ep_gw'][gw] for i in xi); cap = max(P[i]['ep_gw'][gw] for i in xi)
        tot = ep+cap
        if best is None or tot>best[0]: best=(tot,(g,d,m,f),xi,ep,cap)
    return best
def obj(ids):
    return sum(best_xi(ids,g)[0] for g in range(6))
def clubs_ok(ids):
    return max(Counter(P[i]['team'] for i in ids).values())<=3
base = obj(set(SQUAD))
print(f"[{label}] BASE 6-GW objective (XI+captain) = {base:.2f}")
for g in range(6):
    t,form,xi,ep,cap = best_xi(set(SQUAD),g)
    capn = max(xi,key=lambda i:P[i]['ep_gw'][g])
    print(f"  GW{4+g}: {t:6.2f} form {form[1]}-{form[2]}-{form[3]} cap {P[capn]['name']} ({cap:.2f}) | " + ", ".join(f"{P[i]['name']}" for i in xi))
# single transfers
singles=[]
for out,sell in SQUAD.items():
    budget = sell+BANK
    for i,r in P.items():
        if i in SQUAD or r['pos']!=P[out]['pos'] or r['price']>budget+1e-9: continue
        ids = set(SQUAD)-{out}|{i}
        if not clubs_ok(ids): continue
        d = obj(ids)-base
        singles.append((d,out,i,budget-r['price']))
singles.sort(reverse=True)
print(f"\n[{label}] TOP SINGLE TRANSFERS (delta on 6-GW XI+cap objective, free):")
for d,out,i,left in singles[:25]:
    r=P[i]; b=B[i]
    print(f"  {d:+6.2f}  {P[out]['name']:11}({SQUAD[out]:4.1f}) -> {r['name']:14} {r['team']} £{r['price']:4.1f} EP6 {r['ep_total6']:5.2f} p {r['p_start']:.2f} {r['uncertainty']:4} own {b['selected_by_percent']:>5}% st {b['status']} cop {b['chance_of_playing_next_round']} left {left:.1f} | {r['notes'][:50]}")
# best per out-player
print(f"\n[{label}] BEST SWAP PER OUT-PLAYER:")
seen=set()
for d,out,i,left in singles:
    if out in seen: continue
    seen.add(out); print(f"  {P[out]['name']:11} -> {P[i]['name']:14} {d:+6.2f}")
# doubles: top 12 singles per out-player, pairwise, -4
cand = {}
for d,out,i,left in singles:
    cand.setdefault(out,[])
    if len(cand[out])<12: cand[out].append(i)
doubles=[]
outs=list(SQUAD)
for o1,o2 in itertools.combinations(outs,2):
    budget = SQUAD[o1]+SQUAD[o2]+BANK
    ins1=[i for i,r in P.items() if i not in SQUAD and r['pos']==P[o1]['pos']]
    ins2=[i for i,r in P.items() if i not in SQUAD and r['pos']==P[o2]['pos']]
    # prune: only top 40 by ep_total6 each
    ins1=sorted(ins1,key=lambda i:-P[i]['ep_total6'])[:40]; ins2=sorted(ins2,key=lambda i:-P[i]['ep_total6'])[:40]
    for i1 in ins1:
        for i2 in ins2:
            if i1==i2: continue
            if P[i1]['price']+P[i2]['price']>budget+1e-9: continue
            ids=set(SQUAD)-{o1,o2}|{i1,i2}
            if not clubs_ok(ids): continue
            d=obj(ids)-base
            doubles.append((d,o1,o2,i1,i2,budget-P[i1]['price']-P[i2]['price']))
doubles.sort(reverse=True)
print(f"\n[{label}] TOP DOUBLE TRANSFERS (gross delta; net = gross-4):")
for d,o1,o2,i1,i2,left in doubles[:20]:
    print(f"  gross {d:+6.2f} net {d-4:+6.2f}  {P[o1]['name']}+{P[o2]['name']} ({SQUAD[o1]+SQUAD[o2]:.1f}) -> {P[i1]['name']} £{P[i1]['price']} + {P[i2]['name']} £{P[i2]['price']}  left {left:.1f}")
# unconstrained ceiling: best XI by EP per GW ignoring budget/club
ceil=0
for g in range(6):
    ceil+=best_xi(set(P),g)[0]
print(f"\n[{label}] CEILING (no budget/club, XI+cap) 6-GW = {ceil:.2f}  per GW {ceil/6:.2f}")
json.dump({'base':base,'singles':singles[:60],'doubles':doubles[:40]}, open(f'{root}/opt-{label}.json','w'))
EOF
